import{_ as t,c as o,o as n,ah as i}from"./chunks/framework.PvdZnrZd.js";const b=JSON.parse('{"title":"Seller Notification","description":"Seller Notification","frontmatter":{"title":"Seller Notification","description":"Seller Notification","date":"2025-07-10T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/seller/seller-notification.md","filePath":"zenith/seller/seller-notification.md"}'),a={name:"zenith/seller/seller-notification.md"};function l(r,e,c,s,p,d){return n(),o("div",null,[...e[0]||(e[0]=[i('<h2 id="introduction" tabindex="-1">Introduction: <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction:&quot;">​</a></h2><p>We have introduced a new feature in our <a href="/zenith/introduction/overview.html">Multivendor Marketplace App</a>. This allows you to send custom notifications to your sellers.</p><p>Check the below video of Seller Notification:</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Let&#39;s dive into the process to configure this feature in your multivendor app for Shopify.</p><p>To enable this, please visit-<br> Multivendor Admin Panel &gt; Sellers &gt; Sellers Notification</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn1.webp" alt="Seller-Notification-Admin"></a></p><p>Clicking on the Seller Notification you would be redirected to the page where you can add as well as check notifications</p><h2 id="add-notification" tabindex="-1">Add Notification <a class="header-anchor" href="#add-notification" aria-label="Permalink to &quot;Add Notification&quot;">​</a></h2><p>You can click on &quot;ADD NOTIFICATION&quot; in order to create a new notification for the sellers</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn2.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn2.webp" alt="add-notification"></a></p><p>To add a new notification you need to enter the title as well as the description of the notification. Now click on submit.</p><p><strong>NOTE-</strong> The title limit is 100 characters and the limit for a notification message is 5000 characters.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn3.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn3.webp" alt="seller-noti"></a></p><p>Now, click on submit and the same will be visible to the sellers on their respective seller panels accordingly.</p><h2 id="seller-notifications" tabindex="-1">Seller Notifications <a class="header-anchor" href="#seller-notifications" aria-label="Permalink to &quot;Seller Notifications&quot;">​</a></h2><p>The latest notification added by the admin will appear on the seller dashboard as a pop-up when sellers will login to their seller dashboard.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn4.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn4.webp" alt="notification-pop"></a></p><h2 id="merchant-notifications" tabindex="-1">Merchant Notifications <a class="header-anchor" href="#merchant-notifications" aria-label="Permalink to &quot;Merchant Notifications&quot;">​</a></h2><p>By clicking on the bell icon, the sellers will be able to view the top 5 recent notifications here added by the admin also they can click on view all to check all the previous notifications</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn5.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn5.webp" alt="notification-bell"></a></p><p>Seller can also view their notification by logging in their panel than going to merchant notification as shown below:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn6.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn6.webp" alt="Merchant-notification-1"></a></p><h2 id="admin-seller-notifications" tabindex="-1">Admin Seller Notifications <a class="header-anchor" href="#admin-seller-notifications" aria-label="Permalink to &quot;Admin Seller Notifications&quot;">​</a></h2><p>Now, the admin can also check their created notification in the notification panel. Also, the admin can view &amp; delete it by clicking on three dots.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn7.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn7.webp" alt="Seller notification"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn8.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn8.webp" alt="View"></a></p><p>View Notification</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn9.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/sn9.webp" alt="Delete"></a></p><p>Delete notification</p>',30)])])}const f=t(a,[["render",l]]);export{b as __pageData,f as default};
